<?php

declare(strict_types=1);

namespace NoResponse;

use InvalidArgumentException;
use NoResponse\Models\Shared\AuthContext;
use NoResponse\Utils\JSON;

/**
 * Auth context adapters. Generated by tools/generate_auth_adapters.py; do not edit.
 *
 * Each adapter maps claims your backend has already verified into the
 * auth_context of an assessment request. Pass verified claims, not a raw token.
 *
 * The mapping is the claim map (contracts/api/v1/fixtures/assessment-contract/
 * auth-context-claim-map.json), run by the small interpreter below. Every SDK
 * runs the same table and the same vectors. A claim that is missing, mistyped
 * or out of range maps to absent, never to a stronger assurance.
 *
 * Claims and overrides are arrays as json_decode($payload, true) gives them.
 * Overrides use the auth_context field names, for example email_verified.
 * Every method throws InvalidArgumentException when the claims have no valid
 * issuer and subject or the provider is not a lowercase slug.
 */
final class Auth
{
    private const CLAIM_MAP_JSON = <<<'JSON'
{"version":1,"kinds":{"id":{"pattern":"[A-Za-z0-9._:@/|+=~-]+","maxLength":256},"audience":{"pattern":"[A-Za-z0-9._:/-]+","maxLength":256},"role":{"pattern":"[A-Za-z0-9._:@/-]+","maxLength":64},"method":{"pattern":"[A-Za-z0-9._:-]+","maxLength":32},"issuer":{"pattern":"https://[\\x21-\\x7e]+","maxLength":256},"time":{"pattern":"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])","maxLength":64}},"slug":"[a-z0-9][a-z0-9._-]{1,31}","constants":{"verified":true,"transport":"backend"},"base":{"issuer":{"op":"id","kind":"issuer","claims":["iss"],"required":true},"subject":{"op":"id","kind":"id","claims":["sub"],"required":true},"audiences":{"op":"list","kind":"audience","claims":["aud"],"split":"whitespace","max":8},"issued_at":{"op":"time","claims":["iat"]},"expires_at":{"op":"time","claims":["exp"]},"auth_time":{"op":"time","claims":["auth_time"]},"session_id":{"op":"id","kind":"id","claims":["sid"]},"token_id":{"op":"id","kind":"id","claims":["jti"]}},"providers":{"workos":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"roles":{"op":"list","kind":"role","claims":["roles","role"],"split":"whitespace","max":32},"scopes":{"op":"list","kind":"role","claims":["permissions"],"split":"whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]}}},"clerk":{"disable":["issued_at"],"fields":{"organization_id":{"op":"id","kind":"id","claims":["o.id","org_id"]},"roles":{"op":"list","kind":"role","claims":["o.rol","org_role"],"split":"none","max":32},"scopes":{"op":"list","kind":"role","claims":["o.per","org_permissions"],"split":"comma_whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_factor_age","claim":"fva","index":1,"unitSeconds":60,"maxSeconds":315360000}}},"auth0":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"scopes":{"op":"list","kind":"role","claims":["scope","permissions"],"split":"whitespace","max":32},"email_verified":{"op":"bool","claims":["email_verified"]},"phone_verified":{"op":"bool","claims":["phone_number_verified"]},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_methods","kind":"method","claim":"amr","max":8,"mfaValue":"mfa","ignore":["pwd"]}}},"supabase":{"disable":["auth_time"],"fields":{"session_id":{"op":"id","kind":"id","claims":["session_id"]},"roles":{"op":"list","kind":"role","claims":["role"],"split":"none","max":1},"mfa":{"op":"mfa_aal","claim":"aal","present":["aal2"],"absent":["aal1"],"amr":"amr","methodKey":"method","factors":{"totp":"totp","mfa/phone":"mfa:phone","mfa/webauthn":"mfa:webauthn","mfa/recovery_code":"mfa:recovery_code"}},"assurance_level":{"op":"marker","value":"low","when":[{"claim":"is_anonymous","equals":true},{"claim":"app_metadata.provider","equals":"anonymous"}]}}},"firebase":{"disable":["session_id","token_id"],"fields":{"tenant_id":{"op":"id","kind":"id","claims":["firebase.tenant"]},"mfa":{"op":"mfa_factor","kind":"method","claim":"firebase.sign_in_second_factor"},"assurance_level":{"op":"marker","value":"low","when":[{"claim":"firebase.sign_in_provider","equals":"anonymous"}]}}},"oidc":{"slugArgument":true,"fields":{}}}}
JSON;

    private const MAX_TIME = 253402300799;

    /** @var array<string, mixed>|null */
    private static ?array $map = null;

    /** @return array<string, mixed> */
    public static function claimMap(): array
    {
        return self::$map ??= json_decode(self::CLAIM_MAP_JSON, true, 512, JSON_THROW_ON_ERROR);
    }

    /**
     * Map verified WorkOS AuthKit claims plus verified user or session record overrides.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromWorkOS(array $claims, ?array $overrides = null): AuthContext
    {
        return self::build('workos', 'workos', $claims, $overrides);
    }

    /**
     * Map verified Clerk session claims. Pass Session.createdAt as the session_created_at override.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromClerk(array $claims, ?array $overrides = null): AuthContext
    {
        return self::build('clerk', 'clerk', $claims, $overrides);
    }

    /**
     * Map verified Auth0 ID token, userinfo or normalised session claims. Do not pass an opaque API access token.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromAuth0(array $claims, ?array $overrides = null): AuthContext
    {
        return self::build('auth0', 'auth0', $claims, $overrides);
    }

    /**
     * Map verified Supabase Auth access token claims (legacy HS256 secret or JWKS). Pass the user record's contact verification as overrides.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromSupabase(array $claims, ?array $overrides = null): AuthContext
    {
        return self::build('supabase', 'supabase', $claims, $overrides);
    }

    /**
     * Map verified Firebase ID token claims from the Admin SDK verifyIdToken. Custom claims never change the mapping.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromFirebase(array $claims, ?array $overrides = null): AuthContext
    {
        return self::build('firebase', 'firebase', $claims, $overrides);
    }

    /**
     * Generic OIDC adapter for providers without a first-class helper. $provider is a lowercase slug.
     *
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>|null  $overrides
     */
    public static function fromOIDC(string $provider, array $claims, ?array $overrides = null): AuthContext
    {
        if (preg_match('#^(?:'.self::claimMap()['slug'].')\z#D', $provider) !== 1) {
            throw new InvalidArgumentException('provider must be a lowercase provider slug');
        }

        return self::build('oidc', $provider, $claims, $overrides);
    }

    private static function isList(mixed $value): bool
    {
        return is_array($value) && array_is_list($value);
    }

    private static function isObject(mixed $value): bool
    {
        return is_array($value) && ! array_is_list($value);
    }

    private static function isNumber(mixed $value): bool
    {
        return is_int($value) || (is_float($value) && is_finite($value));
    }

    /** @param  array<string, mixed>  $claims */
    private static function lookup(array $claims, string $path): mixed
    {
        $current = $claims;
        foreach (explode('.', $path) as $key) {
            if (! self::isObject($current) || ! array_key_exists($key, $current)) {
                return null;
            }
            $current = $current[$key];
        }

        return $current;
    }

    private static function matches(string $kind, mixed $value): bool
    {
        if (! is_string($value)) {
            return false;
        }
        $spec = self::claimMap()['kinds'][$kind];

        // Every pattern is ASCII only, so a match makes bytes equal characters.
        return preg_match('#^(?:'.$spec['pattern'].')\z#D', $value) === 1 && strlen($value) <= $spec['maxLength'];
    }

    private static function lower(string $value): string
    {
        return strtr($value, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz');
    }

    /**
     * @param  array<string, mixed>  $claims
     * @param  array<string, mixed>  $rule
     */
    private static function mapRule(array $claims, array $rule): mixed
    {
        switch ($rule['op']) {
            case 'id':
                foreach ($rule['claims'] as $path) {
                    $value = self::lookup($claims, $path);
                    if (self::matches($rule['kind'], $value)) {
                        return $value;
                    }
                }

                return null;
            case 'list':
                foreach ($rule['claims'] as $path) {
                    $value = self::lookup($claims, $path);
                    $items = [];
                    if (is_string($value)) {
                        $split = $rule['split'] ?? 'whitespace';
                        $pattern = $split === 'comma_whitespace' ? '/[ \t\r\n\f\x0B,]+/' : '/[ \t\r\n\f\x0B]+/';
                        $items = $split === 'none' ? [$value] : preg_split($pattern, $value);
                    } elseif (self::isList($value)) {
                        $items = $value;
                    }
                    $kept = [];
                    foreach ($items as $item) {
                        if (self::matches($rule['kind'], $item) && count($kept) < $rule['max']) {
                            $kept[] = $item;
                        }
                    }
                    if ($kept !== []) {
                        return $kept;
                    }
                }

                return null;
            case 'time':
                foreach ($rule['claims'] as $path) {
                    $value = self::lookup($claims, $path);
                    if (self::isNumber($value) && $value >= 0 && $value <= self::MAX_TIME) {
                        // Whole UTC seconds; the fraction is truncated.
                        return gmdate('Y-m-d\TH:i:s\Z', (int) $value);
                    }
                    if (self::matches('time', $value)) {
                        return $value;
                    }
                }

                return null;
            case 'bool':
                foreach ($rule['claims'] as $path) {
                    $value = self::lookup($claims, $path);
                    if (is_bool($value)) {
                        return $value;
                    }
                }

                return null;
            case 'actor':
                $value = self::lookup($claims, $rule['claims'][0]);
                if (self::isObject($value)) {
                    foreach (['sub', 'email'] as $key) {
                        if (isset($value[$key]) && is_string($value[$key]) && $value[$key] !== '') {
                            return true;
                        }
                    }

                    return false;
                }

                return is_string($value) && $value !== '';
            case 'mfa_factor_age':
                $value = self::lookup($claims, $rule['claim']);
                if (! self::isList($value) || ! isset($value[$rule['index']]) || ! self::isNumber($value[$rule['index']])) {
                    return null;
                }
                $seconds = $value[$rule['index']] * $rule['unitSeconds'];
                if ($seconds < 0 || $seconds > $rule['maxSeconds']) {
                    return null;
                }

                return ['present' => true, 'age_seconds' => (int) $seconds];
            case 'mfa_aal':
                $level = self::lookup($claims, $rule['claim']);
                if (! is_string($level)) {
                    return null;
                }
                if (in_array($level, $rule['absent'], true)) {
                    return ['present' => false];
                }
                if (! in_array($level, $rule['present'], true)) {
                    return null;
                }
                $entries = self::lookup($claims, $rule['amr']);
                $methods = [];
                foreach (self::isList($entries) ? $entries : [] as $entry) {
                    $name = self::isObject($entry) ? ($entry[$rule['methodKey']] ?? null) : $entry;
                    $mapped = is_string($name) ? ($rule['factors'][$name] ?? null) : null;
                    if ($mapped !== null && ! in_array($mapped, $methods, true)) {
                        $methods[] = $mapped;
                    }
                }

                return $methods === [] ? ['present' => true] : ['present' => true, 'methods' => $methods];
            case 'mfa_factor':
                $value = self::lookup($claims, $rule['claim']);

                return self::matches($rule['kind'], $value) ? ['present' => true, 'methods' => [$value]] : null;
            case 'marker':
                foreach ($rule['when'] as $test) {
                    if (self::lookup($claims, $test['claim']) === $test['equals']) {
                        return $rule['value'];
                    }
                }

                return null;
            case 'mfa_methods':
                $value = self::lookup($claims, $rule['claim']);
                if (! self::isList($value)) {
                    return null;
                }
                $kept = [];
                foreach ($value as $item) {
                    if (self::matches($rule['kind'], $item) && count($kept) < $rule['max']) {
                        $kept[] = $item;
                    }
                }
                $methods = array_values(array_filter($kept, fn (string $item): bool => ! in_array(self::lower($item), $rule['ignore'], true)));
                if ($methods === []) {
                    return null;
                }
                $present = false;
                foreach ($kept as $item) {
                    if (self::lower($item) === $rule['mfaValue']) {
                        $present = true;
                    }
                }

                return ['present' => $present, 'methods' => $methods];
            default:
                throw new InvalidArgumentException('unknown claim map op '.$rule['op']);
        }
    }

    /**
     * @param  array<string, mixed>|null  $value
     * @return array<string, mixed>
     */
    private static function normalise(?array $value): array
    {
        $decoded = json_decode(json_encode($value ?? new \stdClass(), JSON_THROW_ON_ERROR), true, 512, JSON_THROW_ON_ERROR);

        return is_array($decoded) ? $decoded : [];
    }

    /**
     * @param  array<string, mixed>  $rawClaims
     * @param  array<string, mixed>|null  $rawOverrides
     */
    private static function build(string $name, string $provider, array $rawClaims, ?array $rawOverrides): AuthContext
    {
        $map = self::claimMap();
        $claims = self::normalise($rawClaims);
        $overrides = self::normalise($rawOverrides);
        $spec = $map['providers'][$name];
        $rules = array_merge($map['base'], $spec['fields']);
        foreach ($spec['disable'] ?? [] as $field) {
            unset($rules[$field]);
        }
        $wire = array_merge(['provider' => $provider], $map['constants']);
        foreach ($rules as $field => $rule) {
            $value = self::mapRule($claims, $rule);
            if ($value !== null) {
                $wire[$field] = $value;
            }
        }
        foreach ($overrides as $field => $value) {
            if ($value !== null) {
                $wire[$field] = $value;
            }
        }
        if (isset($wire['audiences']) && is_array($wire['audiences']) && $wire['audiences'] !== [] && ! array_key_exists('audience', $wire)) {
            $wire['audience'] = array_values($wire['audiences'])[0];
        }
        foreach (['issuer', 'subject'] as $key) {
            if (! isset($wire[$key]) || ! is_string($wire[$key]) || $wire[$key] === '') {
                throw new InvalidArgumentException('NoResponse auth context requires a verified issuer and subject');
            }
        }

        return JSON::createSerializer()->deserialize(json_encode($wire, JSON_THROW_ON_ERROR), AuthContext::class, 'json');
    }
}
